WITH enriched AS (SELECT id, store_name, city, opened_date, sqft, AVG(sqft) OVER (PARTITION BY city, region ORDER BY sqft, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_sqft, COUNT(sqft) OVER (PARTITION BY city, region ORDER BY sqft, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_sqft, MAX(sqft) OVER (PARTITION BY city, region ORDER BY sqft, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_sqft FROM stores) SELECT id, store_name, sqft, last3_count_sqft, last3_max_sqft, CASE WHEN store_name RLIKE '^(Downtown Express|Siam Flagship)$' THEN 'CORE' WHEN store_name RLIKE '^(Airport Kiosk|Mall Central)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS store_name_zone FROM enriched;
